suppressPackageStartupMessages({library(ggplot2);library(dplyr);library(readr)})
args<-commandArgs(FALSE);script<-sub("^--file=","",args[grep("^--file=",args)][1]);root<-normalizePath(file.path(dirname(script),".."))
dat<-suppressMessages(read_tsv(file.path(root,"results","MreB_ALP_ARD_transition_contribution_summary_six_trees.tsv")))
figdir<-file.path(root,"figures");srcdir<-file.path(root,"source_data");dir.create(figdir,FALSE,TRUE);dir.create(srcdir,FALSE,TRUE)
tree_levels<-c("GTDB r226","A1338 add-core","A1338 de novo","A1338 ASTRAL64","Asgard971 add-core","Asgard971 ASTRAL89")
tree_cols<-c("GTDB r226"="#333333","A1338 add-core"="#D28E35","A1338 de novo"="#B95B66","A1338 ASTRAL64"="#8066A6","Asgard971 add-core"="#2D8C8C","Asgard971 ASTRAL89"="#4E78B4")
tree_shapes<-c("GTDB r226"=16,"A1338 add-core"=17,"A1338 de novo"=15,"A1338 ASTRAL64"=18,"Asgard971 add-core"=8,"Asgard971 ASTRAL89"=3)
labels<-c(GTDB_r226="GTDB r226",A1338_addcore="A1338 add-core",A1338_denovo="A1338 de novo",A1338_ASTRAL64="A1338 ASTRAL64",Asgard971_addcore="Asgard971 add-core",Asgard971_ASTRAL89="Asgard971 ASTRAL89")
plotdat<-bind_rows(dat%>%transmute(tree,route="Coexist-mediated",percent=100*coexist_mediated_fraction),dat%>%transmute(tree,route="Direct endpoint transition",percent=100*direct_endpoint_fraction))%>%mutate(tree_label=factor(recode(tree,!!!labels),levels=tree_levels),route=factor(route,levels=c("Coexist-mediated","Direct endpoint transition")))
write_tsv(plotdat,file.path(srcdir,"MreB_ALP_ARD_transition_contribution_six_trees_figure_data.tsv"))
p<-ggplot(plotdat,aes(route,percent,group=route))+geom_boxplot(width=.42,size=.34,outlier.shape=NA,fill=NA,colour="#8B8B8B")+geom_jitter(aes(colour=tree_label,shape=tree_label),width=.08,height=0,size=2.15,stroke=.45)+scale_colour_manual(values=tree_cols,name=NULL)+scale_shape_manual(values=tree_shapes,name=NULL)+scale_y_continuous(limits=c(0,100),breaks=seq(0,100,20),expand=expansion(mult=c(.01,.03)))+scale_x_discrete(labels=c("Coexist-mediated\ntransitions","Direct endpoint\ntransitions"))+labs(x=NULL,y="Share of inferred ARD transitions (%)",title="MreB–ALP ARD transition-route contributions",caption="Fixed-Q stochastic-history posterior means; six species-tree reconstructions; unit topology.")+theme_classic(base_size=7.2,base_family="Arial")+theme(axis.line=element_line(size=.30),axis.ticks=element_line(size=.28),axis.text.x=element_text(size=6.5),axis.text.y=element_text(size=6.3),plot.title=element_text(size=8.2,face="bold"),plot.caption=element_text(size=5.3,colour="#555555"),legend.position="top",legend.text=element_text(size=5.8),plot.margin=margin(3,6,3,5))
ggsave(file.path(figdir,"fig_mreb_alp_ARD_transition_contribution_six_trees.pdf"),p,width=142,height=96,units="mm",device=cairo_pdf)
ggsave(file.path(figdir,"fig_mreb_alp_ARD_transition_contribution_six_trees.png"),p,width=142,height=96,units="mm",dpi=600,bg="white")
